  void BuildStudioManager(){string heading=focusSection=="decor"?"Kafenin tarzını seç.":focusSection=="delivery"?"Her sipariş doğru kişiye.":focusSection=="supply"?"Her fincan için hazır ol.":focusSection=="upgrade"?"Kafene yatırım yap.":focusSection=="report"?"İyi servis iz bırakır.":focusSection=="ranking"?"Caddenin favorisi ol.":focusSection=="settings"?"Sana göre bir deneyim.":focusSection=="recipes"?"İyi kahvenin reçetesi.":"Bugün kafende neler oluyor?";StudioChrome("İŞLETME / YÖNETİM",heading,focusSection=="decor"?"Seviye atla, yeni tarzlar aç. Seçtiğin görünümü istediğinde değiştir.":"Anlık durum, doğru kararlar ve bir sonraki hedefin.");StudioNav();var d=game.data;var x=game.expansion;var h=game.GetComponent<CafeHundred>();
