   else{SCard(focusSection=="supply"?"ÇEKİRDEK":"BUGÜNKÜ SERVİS",focusSection=="supply"?d.beans.ToString():x.Data.dayServed.ToString(),focusSection=="supply"?"Depoda "+d.depotBeans:"Toplam "+d.served,268,220,300);SCard(focusSection=="supply"?"SÜT / BUZ":"İTİBAR",focusSection=="supply"?d.milk+" / "+d.ice:"%"+Mathf.RoundToInt(d.reputation),"Kafe Lv."+Economy.Level(d),590,220,300);SCard("NET GELİR",(x.Data.dayIncome-x.Data.dayExpenses)+" coin","Bugünün gelir eksi gideri",912,220,338);}
